from pathlib import Path

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                rr,cc=stack.pop(); cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            objs.append((color,cells))
    positions=[set(cells) for _,cells in objs]
    # Slide pieces to the right, advancing rightmost pieces first; repeat until packed.
    order=sorted(range(len(objs)), key=lambda i:max(c for r,c in positions[i]), reverse=True)
    changed=True
    while changed:
        changed=False
        for i in order:
            own=positions[i]
            others=set().union(*(positions[j] for j in range(len(objs)) if j!=i)) if len(objs)>1 else set()
            shifted={(r,c+1) for r,c in own}
            if all(c<w for r,c in shifted) and not (shifted & others):
                positions[i]=shifted; changed=True
    out=[[0]*w for _ in range(h)]
    for (color,_), cells in zip(objs,positions):
        for r,c in cells: out[r][c]=color
    return out

